"use client";
import React, { useEffect, useState } from "react";
import { getAllUsers } from "@/features/users/api";

function UsersList() {
  const [users, setUsers] = useState<any[]>([]);

  useEffect(() => {
    (async () => {
      try {
        const data = await getAllUsers();
        setUsers(data);
      } catch (err) {
        console.error(err);
      }
    })();
  }, []);

  return (
    <div>
      <h1>Users</h1>
      <ul>
        {users.map((u) => (
          <li key={u.userId}>
            {u.firstName} {u.lastName}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default UsersList;
