  name: string;
  age: number;
};

function UserCard({ name, age }: UserCardProps) {
  return (
    <div>
      <h2>{name}</h2>
      <p>Yoshi: {age}</p>
    </div>
  );
}
```

---

### 2️⃣ `React.FC` (Functional Component) bilan  
```tsx
type UserCardProps = {
  name: string;
  age: number;
};

const UserCard: React.FC<UserCardProps> = ({ name, age }) => {
  return (
    <div>
      <h2>{name}</h2

dProps = {
  name: string;
  age: number;
};

const UserCard: React.FC<UserCardProps> = ({ name, age }) => {
  return (
    <div>
      <h2>{name}</h2>
      <p>Yoshi: {age}</p>
    </div>
